/**
 * The bootstrap reproduces packages/fixtures/reference-results/pls-bootstrap (generated by
 * packages/fixtures/scripts/make_bootstrap_references.R with cSEM::csem per draw): every draw's
 * index stream, status and parameter vector, and every SE / t / p / CI.
 */
import { readdirSync } from 'node:fs';
import { afterAll, describe, expect, it } from 'vitest';
import type { AnalysisConfiguration, SemModel } from '@sem-studio/contracts';
import { NormalizedSemResult } from '@sem-studio/contracts';
import {
  bootstrapIndices,
  type BootstrapProblem,
  coreModel,
  estimatePls,
  fitDraw,
  prepareData,
  summariseBootstrap,
  thetaEntries,
  validateRequest,
} from '../src/index.ts';
import { analysisData, FIXTURES, loadCase, readJson } from './helpers.ts';

interface RefDraw {
  b: number;
  idxSum: number;
  status: 'ok' | 'failed' | 'inadmissible';
  reason?: string;
  checks?: string[];
  theta?: number[];
}
interface RefParam {
  key: string;
  kind: string;
  est: number | null;
  nValid: number;
  se: number | null;
  statistic: number | null;
  pValue: number | null;
  ciLower: number | null;
  ciUpper: number | null;
}
interface BootRef {
  case: string;
  rows: number;
  seed: number;
  B: number;
  request: { model: SemModel; analysis: AnalysisConfiguration };
  thetaKeys: string[];
  estimate: number[];
  counts: { requested: number; completed: number; failed: number; inadmissible: number };
  draws: RefDraw[];
  parameters: RefParam[];
}

const DIR = `${FIXTURES}reference-results/pls-bootstrap/`;
const files = readdirSync(DIR)
  .filter((f) => f.endsWith('.json'))
  .sort();
const TOL = 1e-10;
const dev = { draws: 0, inadmissibleDraws: 0, se: 0, ci: 0, p: 0, t: 0 };

function setup(ref: BootRef) {
  const { csv } = loadCase(ref.case);
  const data = analysisData(ref.request.model, {
    header: csv.header,
    rows: csv.rows.slice(0, ref.rows),
  });
  const analysis = { ...ref.request.analysis, engine: 'browser' as const };
  return { data, analysis };
}

afterAll(() => {
  process.stderr.write(
    `PLS bootstrap parity (${files.length} references): max |Δ| draws (valid) ${dev.draws.toExponential(2)}, ` +
      `inadmissible-draw estimates ${dev.inadmissibleDraws.toExponential(2)}, se ${dev.se.toExponential(2)}, ` +
      `t ${dev.t.toExponential(2)}, p ${dev.p.toExponential(2)}, CI ${dev.ci.toExponential(2)}\n`,
  );
});

describe('bootstrap reproduces the R reference (cSEM::csem per draw)', () => {
  it('has the reference files', () => {
    expect(files).toEqual(
      expect.arrayContaining([
        'tam-mediation__pls-sem.json',
        'tam-mediation__plsc.json',
        'pls-mixed-composite__pls-sem.json',
        'delone-mclean__pls-sem.json',
      ]),
    );
  });

  for (const file of files) {
    it(`${file}: every draw (indices, status, estimates)`, () => {
      const ref = readJson<BootRef>(DIR + file);
      const { data, analysis } = setup(ref);
      const spec = validateRequest(ref.request.model, analysis);
      const prepared = prepareData(spec, data);
      const theta = thetaEntries(spec);
      expect(theta.map((t) => t.key)).toEqual(ref.thetaKeys);
      const problem: BootstrapProblem = {
        core: coreModel(spec),
        disattenuate: spec.method === 'plsc',
        columns: prepared.columns,
        theta,
      };
      const results = [];
      let b = 0;
      for (const idx of bootstrapIndices(ref.seed, prepared.n, ref.B)) {
        const r = ref.draws[b++]!;
        // R's indices are 1-based
        expect(
          idx.reduce((s, v) => s + v + 1, 0),
          `draw ${r.b} index stream`,
        ).toBe(r.idxSum);
        const d = fitDraw(problem, idx);
        results.push(d);
        expect(d.status, `draw ${r.b}`).toBe(r.status);
        if (d.status === 'failed') expect(d.reason, `draw ${r.b}`).toBe(r.reason);
        if (d.status === 'inadmissible') {
          expect(d.checks, `draw ${r.b}`).toEqual(r.checks);
          d.theta.forEach((v, i) => {
            const delta = Math.abs(v - r.theta![i]!);
            dev.inadmissibleDraws = Math.max(dev.inadmissibleDraws, delta);
            expect(delta, `inadmissible draw ${r.b} ${ref.thetaKeys[i]}`).toBeLessThanOrEqual(TOL);
          });
        }
        if (d.status === 'ok') {
          d.theta.forEach((v, i) => {
            const delta = Math.abs(v - r.theta![i]!);
            dev.draws = Math.max(dev.draws, delta);
            expect(delta, `draw ${r.b} ${ref.thetaKeys[i]}`).toBeLessThanOrEqual(TOL);
          });
        }
      }
      const counts = summariseBootstrap(results);
      expect({ ...counts, valid: undefined }).toEqual({ ...ref.counts, valid: undefined });
      expect(counts.requested).toBe(counts.completed + counts.failed + counts.inadmissible);
    });

    it(`${file}: estimatePls inference (se, t, p, CI) equals the reference`, async () => {
      const ref = readJson<BootRef>(DIR + file);
      const { data, analysis } = setup(ref);
      const out = await estimatePls({ model: ref.request.model, analysis, data });
      if (!out.ok) throw new Error(`${out.error.code}: ${out.error.message}`);
      expect(() => NormalizedSemResult.parse(out.result)).not.toThrow();
      const bs = out.result.bootstrap!;
      expect({
        requested: bs.requested,
        completed: bs.completed,
        failed: bs.failed,
        inadmissible: bs.inadmissible,
      }).toEqual(ref.counts);
      expect(bs.seed).toBe(ref.seed);
      const byKey = new Map(out.result.parameters.map((p) => [p.key, p]));
      for (const rp of ref.parameters) {
        const tp = byKey.get(rp.key);
        expect(tp, rp.key).toBeDefined();
        expect(tp!.inference?.nValid, rp.key).toBe(rp.nValid);
        const cmp = (a: number | null, b: number | null, what: keyof typeof dev): void => {
          if (a === null || b === null) {
            expect(a, `${rp.key} ${what}`).toBe(b);
            return;
          }
          const d = Math.abs(a - b);
          dev[what] = Math.max(dev[what], d);
          expect(d, `${rp.key} ${what}: ${a} vs ${b}`).toBeLessThanOrEqual(TOL);
        };
        cmp(tp!.est, rp.est, 'draws');
        cmp(tp!.se, rp.se, 'se');
        cmp(tp!.statistic, rp.statistic, 't');
        cmp(tp!.pValue, rp.pValue, 'p');
        cmp(tp!.ciLower, rp.ciLower, 'ci');
        cmp(tp!.ciUpper, rp.ciUpper, 'ci');
      }
    });
  }
});
